// Generated by Automated Quality Gate; review before merging.
const { total } = require('../../src/cart');

describe('cart total function', () => {
  test('should return 0 for an empty array', () => {
    expect(total([])).toBe(0);
  });

  test('should calculate the total price for a single item', () => {
    const items = [{ price: 10, quantity: 2 }];
    expect(total(items)).toBe(20);
  });

  test('should calculate the total price for multiple items', () => {
    const items = [
      { price: 10, quantity: 2 },
      { price: 5, quantity: 3 },
      { price: 100, quantity: 1 }
    ];
    expect(total(items)).toBe(135);
  });

  test('should handle items with zero quantity', () => {
    const items = [{ price: 100, quantity: 0 }];
    expect(total(items)).toBe(0);
  });

  test('should handle items with zero price', () => {
    const items = [{ price: 0, quantity: 5 }];
    expect(total(items)).toBe(0);
  });

  test('should throw a TypeError if input is not an array', () => {
    const invalidInputs = [null, undefined, {}, 'string', 123];
    
    invalidInputs.forEach((input) => {
      expect(() => {
        total(input);
      }).toThrow(TypeError);
      
      expect(() => {
        total(input);
      }).toThrow('items must be an array');
    });
  });

  test('should handle floating point math correctly', () => {
    const items = [
      { price: 0.1, quantity: 1 },
      { price: 0.2, quantity: 1 }
    ];
    // Using toBeCloseTo for floating point precision
    expect(total(items)).toBeCloseTo(0.3);
  });
});
